apiVersion: flagger.app/v1beta1
kind: MetricTemplate
metadata:
  name: apdex-score
spec:
  provider:
    type: prometheus
    address: http://prometheus.monitoring:9090
  query: |
    sum(rate(http_request_duration_seconds_bucket{
      namespace="{{ namespace }}",
      le="0.25"
    }[5m])) by (service)
    /
    sum(rate(http_request_duration_seconds_count{
      namespace="{{ namespace }}"
    }[5m])) by (service)
    +
    sum(rate(http_request_duration_seconds_bucket{
      namespace="{{ namespace }}",
      le="1"
    }[5m])) by (service)
    /
    sum(rate(http_request_duration_seconds_count{
      namespace="{{ namespace }}"
    }[5m])) by (service)
    / 2
